values
  ('a31bc414-59bd-4410-98ad-35ce96ffc910', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', null, 'topic'::public.curated_course_node_type, 'What Is Theater?', 'This opening section gives students a flexible definition of theater as a live, collaborative, embodied event. It helps them see theater not only as plays on stages, but as a cultural practice shaped by people, place, time, and audience.', 0),
  ('672888ea-9b18-4b06-8d61-f4b9bb5bc70a', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'a31bc414-59bd-4410-98ad-35ce96ffc910', 'subtopic'::public.curated_course_node_type, 'Liveness and co-presence', 'Students learn why theater changes when performers and audiences share time and space.', 0),
  ('5b3e94c5-581e-4873-835b-b2dd3c8bb930', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '672888ea-9b18-4b06-8d61-f4b9bb5bc70a', 'concept'::public.curated_course_node_type, 'Live event and repeatability', null, 0),
  ('4823f701-1d87-48ca-bedd-1e6e2c670bfa', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '672888ea-9b18-4b06-8d61-f4b9bb5bc70a', 'concept'::public.curated_course_node_type, 'Presence and attention', null, 1),
  ('5909f49f-8f78-4d10-b7d4-8c3cfc925cc5', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '672888ea-9b18-4b06-8d61-f4b9bb5bc70a', 'concept'::public.curated_course_node_type, 'Risk, error, and immediacy', null, 2),
  ('19425a26-3783-4944-b7a9-76c4878b85f1', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'a31bc414-59bd-4410-98ad-35ce96ffc910', 'subtopic'::public.curated_course_node_type, 'Theater as representation and action', 'The point is to understand that theater both depicts worlds and performs actions in the real world.', 1),
  ('601ae098-9ebd-4f86-9d37-a7d6320fcc33', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '19425a26-3783-4944-b7a9-76c4878b85f1', 'concept'::public.curated_course_node_type, 'Story and event', null, 0),
