  ('ca2fe236-d40e-44af-8f0a-b717542ff7da', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'b96f48e3-c2c4-4990-ae65-2dd58e8a7abf', 'concept'::public.curated_course_node_type, 'Performance studies basics', null, 0),
  ('6f16c183-d89f-4fef-8232-989805690c52', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'b96f48e3-c2c4-4990-ae65-2dd58e8a7abf', 'concept'::public.curated_course_node_type, 'Role-playing and social behavior', null, 1),
  ('b6b2f1cf-733c-4a62-9491-93815fb0ddf3', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'b96f48e3-c2c4-4990-ae65-2dd58e8a7abf', 'concept'::public.curated_course_node_type, 'Public events and spectacle', null, 2),
  ('4f8667cc-de46-499b-9906-052aebce20df', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'a31bc414-59bd-4410-98ad-35ce96ffc910', 'subtopic'::public.curated_course_node_type, 'Theater as labor and institution', 'Theater is also work. Students learn the economic, organizational, and community structures behind the art.', 3),
