  ('5162c1a7-c556-4cce-969f-abc987b42466', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '4f8667cc-de46-499b-9906-052aebce20df', 'concept'::public.curated_course_node_type, 'Education and community theater', null, 1),
  ('9fac6b04-0312-445b-99a3-939f4d85d891', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '4f8667cc-de46-499b-9906-052aebce20df', 'concept'::public.curated_course_node_type, 'Unions, labor, and professional pathways', null, 2),
  ('2a284ffc-1dec-47c5-8b5f-39ac28333c27', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', null, 'topic'::public.curated_course_node_type, 'Theater''s Origins and History', 'This section introduces theater history as a set of many traditions rather than one single lineage. Students learn how performance forms respond to religion, politics, commerce, architecture, technology, and social change.', 1),
  ('2f9fdf9f-7968-4c3e-a3a6-cdac6a4fa1a4', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '2a284ffc-1dec-47c5-8b5f-39ac28333c27', 'subtopic'::public.curated_course_node_type, 'Ritual, festival, and early performance', 'Students explore how performance emerges from communal gatherings, ceremony, storytelling, and embodied memory.', 0),
  ('cfc0133c-1f72-4d19-833d-c4bb5e1afb07', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '2f9fdf9f-7968-4c3e-a3a6-cdac6a4fa1a4', 'concept'::public.curated_course_node_type, 'Ritual action', null, 0),
  ('070cd4d5-62d2-47d4-b1b8-f875b8065f20', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '2f9fdf9f-7968-4c3e-a3a6-cdac6a4fa1a4', 'concept'::public.curated_course_node_type, 'Festival calendars', null, 1),
  ('a10ac4b8-0d44-4de8-b217-947e341ad036', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '2f9fdf9f-7968-4c3e-a3a6-cdac6a4fa1a4', 'concept'::public.curated_course_node_type, 'Myth and community identity', null, 2),
  ('83aa2381-6e4a-4221-ae03-1f94a6720435', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '2a284ffc-1dec-47c5-8b5f-39ac28333c27', 'subtopic'::public.curated_course_node_type, 'Classical and premodern traditions', 'The goal is to recognize major forms while avoiding the idea that one tradition explains all theater.', 1),
  ('fea0ba85-85ff-48b1-9ccf-1201ecb4aa45', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '83aa2381-6e4a-4221-ae03-1f94a6720435', 'concept'::public.curated_course_node_type, 'Greek tragedy and comedy', null, 0),
