  ('26a338ec-2cc3-486d-9470-f884a51f5e32', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '2a284ffc-1dec-47c5-8b5f-39ac28333c27', 'subtopic'::public.curated_course_node_type, 'Commercial, court, and public theaters', 'Students learn how architecture, patronage, censorship, and audiences shape theater forms.', 2),
