  ('e5f6a9f5-dc42-45fa-bf4b-6f9bdb60d09e', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '26a338ec-2cc3-486d-9470-f884a51f5e32', 'concept'::public.curated_course_node_type, 'Commedia dell''arte', null, 1),
  ('0bb5f415-ef13-4f18-bba0-e2b41384b04a', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '26a338ec-2cc3-486d-9470-f884a51f5e32', 'concept'::public.curated_course_node_type, 'Restoration and neoclassical stages', null, 2),
  ('f0ca412e-46ab-4b5d-b615-8f4201a708f4', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '2a284ffc-1dec-47c5-8b5f-39ac28333c27', 'subtopic'::public.curated_course_node_type, 'Modern and contemporary theater', 'Students trace shifts from realism to modernism, experimental performance, devised work, and global contemporary practice.', 3),
  ('0f039489-b202-4718-9971-08f6a9865b81', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'f0ca412e-46ab-4b5d-b615-8f4201a708f4', 'concept'::public.curated_course_node_type, 'Realism and naturalism', null, 0),
  ('81639dde-126e-44aa-88bb-9e603899c33d', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'f0ca412e-46ab-4b5d-b615-8f4201a708f4', 'concept'::public.curated_course_node_type, 'Modernist and avant-garde movements', null, 1),
  ('53682c45-7666-4ec0-8480-e929532fc572', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'f0ca412e-46ab-4b5d-b615-8f4201a708f4', 'concept'::public.curated_course_node_type, 'Postcolonial, feminist, queer, and community-based theater', null, 2),
  ('8966846b-9708-4c88-b4c7-9f10b5516a64', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', null, 'topic'::public.curated_course_node_type, 'The Collaborative Art Form', 'Theater is made through interdependent craft. This section helps students understand how creative, technical, managerial, and audience roles connect.', 2),
  ('36e68c00-8182-456d-b101-0be9b10963b4', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '8966846b-9708-4c88-b4c7-9f10b5516a64', 'subtopic'::public.curated_course_node_type, 'Production roles and responsibilities', 'Students learn who does what in a production and how those responsibilities overlap.', 0),
  ('cf08399b-d49b-44de-b605-07c057cc0dd0', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '36e68c00-8182-456d-b101-0be9b10963b4', 'concept'::public.curated_course_node_type, 'Creative team', null, 0),
  ('89628b99-bc3c-495e-80be-5bc69d10756a', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '36e68c00-8182-456d-b101-0be9b10963b4', 'concept'::public.curated_course_node_type, 'Production team', null, 1),
  ('f8f97755-86a4-4963-ad8f-c13fd88fb70f', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '36e68c00-8182-456d-b101-0be9b10963b4', 'concept'::public.curated_course_node_type, 'Front-of-house and producing', null, 2),
  ('748d474a-a3b9-4304-829f-8379a71acf01', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '8966846b-9708-4c88-b4c7-9f10b5516a64', 'subtopic'::public.curated_course_node_type, 'Communication across departments', 'The point is to see collaboration as a skill, not just a nice value.', 1);
