  ('98325d6c-fea1-4495-a7b3-022ed0e8e89e', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '8898b7f9-b2d3-46c5-b602-66a609fbf0f8', 'concept'::public.curated_course_node_type, 'Accessibility and inclusion', null, 2),
  ('7e303ebd-4530-4961-a5fe-ea290021889c', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', null, 'topic'::public.curated_course_node_type, 'The Playwright''s Role', 'This section introduces the playwright as an architect of action, language, image, and possibility. Students learn how scripts invite performance choices rather than simply recording dialogue.', 3),
