  ('b0f012f8-5641-4359-8107-79210dfbe0f8', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'c2a42d42-5f67-4b63-8b32-8aeb4bb046af', 'concept'::public.curated_course_node_type, 'Conflict and stakes', null, 0),
  ('990c0512-7d45-4421-901d-10c5b972a97b', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'c2a42d42-5f67-4b63-8b32-8aeb4bb046af', 'concept'::public.curated_course_node_type, 'Events and turning points', null, 1),
  ('af1008aa-d99e-4e7a-87fe-cd5617f41f24', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'c2a42d42-5f67-4b63-8b32-8aeb4bb046af', 'concept'::public.curated_course_node_type, 'Beginnings, middles, and endings', null, 2),
