  ('7306c5cd-c6d8-4f53-889d-16cd5018f705', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'b850e703-0c40-42ab-a12b-29d6696f787a', 'concept'::public.curated_course_node_type, 'Character desire', null, 0),
  ('9fd2e85d-e628-4509-9ef8-d1f8d96d0654', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'b850e703-0c40-42ab-a12b-29d6696f787a', 'concept'::public.curated_course_node_type, 'Subtext', null, 1),
  ('686987f0-9d6d-4db5-a063-808b8c266823', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'b850e703-0c40-42ab-a12b-29d6696f787a', 'concept'::public.curated_course_node_type, 'Voice and rhythm', null, 2),
