  ('34ddb5ab-9484-4832-9028-be704e16e38a', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '7718933f-d43a-486a-ad6a-391402899d78', 'concept'::public.curated_course_node_type, 'Image, metaphor, and spectacle', null, 2),
