  ('86cfa10f-7154-4f76-845e-6031b08fedca', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '9b31184e-2465-4b3c-b164-a250225df083', 'concept'::public.curated_course_node_type, 'Dramaturgical feedback', null, 1),
