  ('ef30b565-5ff1-4c59-9582-e11cbcb55826', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', null, 'topic'::public.curated_course_node_type, 'The Director''s Role', 'The director turns analysis into a shared production process. Students learn how directors shape vision, rehearsal, staging, actor collaboration, and design coherence.', 4),
  ('bc282f50-96e2-41bf-89f8-cf00de9c4a67', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'ef30b565-5ff1-4c59-9582-e11cbcb55826', 'subtopic'::public.curated_course_node_type, 'Interpretation and vision', 'Students learn how directors make a case for why this play should be performed in a particular way.', 0),
  ('40b384a8-500b-45de-8bda-877543fbacba', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'bc282f50-96e2-41bf-89f8-cf00de9c4a67', 'concept'::public.curated_course_node_type, 'Director''s concept', null, 0),
  ('d43f5a02-6683-4fed-8ee2-da6edc5d2ddb', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'bc282f50-96e2-41bf-89f8-cf00de9c4a67', 'concept'::public.curated_course_node_type, 'Audience and context', null, 1),
  ('2e81d2c6-a982-45fd-8b07-edb9f49c8704', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'bc282f50-96e2-41bf-89f8-cf00de9c4a67', 'concept'::public.curated_course_node_type, 'Core question or image', null, 2),
  ('f3525b66-cb19-49d3-b480-c26b8bbb32ff', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'ef30b565-5ff1-4c59-9582-e11cbcb55826', 'subtopic'::public.curated_course_node_type, 'Rehearsal leadership', 'The point is to understand rehearsal as planned discovery.', 1),
  ('46bf3985-74cd-4cb8-b3fb-7b961e37f278', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'f3525b66-cb19-49d3-b480-c26b8bbb32ff', 'concept'::public.curated_course_node_type, 'Table work', null, 0),
  ('9756eb31-6d6f-4304-b9a1-f8dbe1c3763d', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'f3525b66-cb19-49d3-b480-c26b8bbb32ff', 'concept'::public.curated_course_node_type, 'Blocking', null, 1),
  ('cd91cdf6-386a-4982-bd2e-4a8318cfcfcc', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'f3525b66-cb19-49d3-b480-c26b8bbb32ff', 'concept'::public.curated_course_node_type, 'Runs, notes, and revision', null, 2),
  ('f2bacb5b-df63-42da-b3ff-7bcb52c20c77', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'ef30b565-5ff1-4c59-9582-e11cbcb55826', 'subtopic'::public.curated_course_node_type, 'Staging and composition', 'Students see how directors use space, bodies, focus, and rhythm to tell the story.', 2),
  ('4c49cf0d-617a-42c6-8738-d5a2b545e363', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'f2bacb5b-df63-42da-b3ff-7bcb52c20c77', 'concept'::public.curated_course_node_type, 'Stage pictures', null, 0),
  ('40813b7d-8e64-4401-a028-324571e2efa5', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'f2bacb5b-df63-42da-b3ff-7bcb52c20c77', 'concept'::public.curated_course_node_type, 'Movement and stillness', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e436b33a-ee0d-4da8-b821-eb4a641202c7', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'f2bacb5b-df63-42da-b3ff-7bcb52c20c77', 'concept'::public.curated_course_node_type, 'Transitions and pacing', null, 2),
  ('acb90297-7481-48fe-98b8-ead7c165010b', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'ef30b565-5ff1-4c59-9582-e11cbcb55826', 'subtopic'::public.curated_course_node_type, 'Collaboration with designers and stage managers', 'Directors coordinate with many artists while respecting each craft area.', 3),
  ('341e4914-f459-47ac-85e4-fc7eb36c63f4', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'acb90297-7481-48fe-98b8-ead7c165010b', 'concept'::public.curated_course_node_type, 'Design meetings', null, 0),
  ('aff221e0-9b4d-4e4a-9788-4dd3d9fa4c50', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'acb90297-7481-48fe-98b8-ead7c165010b', 'concept'::public.curated_course_node_type, 'Prompt books and rehearsal reports', null, 1),
  ('e298df6c-b4b0-4c4c-841b-0fda43a8bb81', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'acb90297-7481-48fe-98b8-ead7c165010b', 'concept'::public.curated_course_node_type, 'Tech rehearsal priorities', null, 2),
  ('ba398fa2-54ba-428d-b3a8-2dedda2ccf10', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', null, 'topic'::public.curated_course_node_type, 'The Actor''s Role', 'Actors make theater visible and audible through body, voice, imagination, listening, and repeatable action. This section introduces actor craft without reducing it to personality or memorization.', 5),
  ('fa5ea237-4d40-4592-84d3-15ed4663ca11', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'ba398fa2-54ba-428d-b3a8-2dedda2ccf10', 'subtopic'::public.curated_course_node_type, 'The actor''s instrument', 'Students learn that acting uses trained physical, vocal, emotional, and imaginative skills.', 0),
  ('11a759f0-b0a9-4a59-b198-52265f4135d7', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'fa5ea237-4d40-4592-84d3-15ed4663ca11', 'concept'::public.curated_course_node_type, 'Body and alignment', null, 0),
  ('51f6dea7-c0b7-43c1-b2b5-9d69d2e3a41c', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'fa5ea237-4d40-4592-84d3-15ed4663ca11', 'concept'::public.curated_course_node_type, 'Voice and breath', null, 1),
  ('ec78a964-28a5-4d43-aa90-a609b68f4cd8', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'fa5ea237-4d40-4592-84d3-15ed4663ca11', 'concept'::public.curated_course_node_type, 'Focus and concentration', null, 2),
  ('627cf655-f18b-4fdb-b22a-64d4f58cea0f', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'ba398fa2-54ba-428d-b3a8-2dedda2ccf10', 'subtopic'::public.curated_course_node_type, 'Objectives and actions', 'The point is to understand acting as doing, not pretending in a vague way.', 1),
  ('737fe25a-e3c2-40e7-9db1-1d888ba23444', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '627cf655-f18b-4fdb-b22a-64d4f58cea0f', 'concept'::public.curated_course_node_type, 'Given circumstances', null, 0),
  ('96178490-fbd0-4669-a1d9-515a662921d9', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '627cf655-f18b-4fdb-b22a-64d4f58cea0f', 'concept'::public.curated_course_node_type, 'Objectives and obstacles', null, 1),
  ('5e253c74-9906-482d-8c85-9190a22b5a8e', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '627cf655-f18b-4fdb-b22a-64d4f58cea0f', 'concept'::public.curated_course_node_type, 'Tactics and playable verbs', null, 2),
  ('a5145b72-1623-4c63-a2f5-3a0348a41637', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'ba398fa2-54ba-428d-b3a8-2dedda2ccf10', 'subtopic'::public.curated_course_node_type, 'Ensemble and listening', 'Theater depends on responsiveness among performers.', 2),
  ('878f5550-cb6c-4fa9-b5af-540b1d48a46a', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'a5145b72-1623-4c63-a2f5-3a0348a41637', 'concept'::public.curated_course_node_type, 'Cue pickup', null, 0),
  ('11f1180c-e9a7-4f83-9d4d-40581bec96c2', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'a5145b72-1623-4c63-a2f5-3a0348a41637', 'concept'::public.curated_course_node_type, 'Status and relationship', null, 1),
  ('635039f7-58a7-4733-9e66-91aff8d61dad', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'a5145b72-1623-4c63-a2f5-3a0348a41637', 'concept'::public.curated_course_node_type, 'Improvisation and trust', null, 2),
  ('977bd816-b8bb-4bd6-8737-9467bf58fb98', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'ba398fa2-54ba-428d-b3a8-2dedda2ccf10', 'subtopic'::public.curated_course_node_type, 'Character and performance style', 'Students compare approaches to realism, heightened language, physical theater, musical performance, and comedy.', 3),
  ('af5456ae-2778-4009-9ef1-7d43581f8087', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '977bd816-b8bb-4bd6-8737-9467bf58fb98', 'concept'::public.curated_course_node_type, 'Character research', null, 0),
  ('b06594e8-2907-4723-9a1f-f5c2caaae533', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '977bd816-b8bb-4bd6-8737-9467bf58fb98', 'concept'::public.curated_course_node_type, 'Style and genre', null, 1),
  ('bd561bc7-7a63-4030-b48c-56fc64503f73', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '977bd816-b8bb-4bd6-8737-9467bf58fb98', 'concept'::public.curated_course_node_type, 'Repeatability and spontaneity', null, 2),
  ('ccadba56-99ef-486b-83b2-8d2fa3780245', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', null, 'topic'::public.curated_course_node_type, 'Designers and Technicians', 'This section gives students production literacy. They learn how scenery, costume, light, sound, props, projections, stage management, and technical work shape meaning.', 6),
  ('9e279f3f-c0e1-46cf-9adb-a446d1f77764', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'ccadba56-99ef-486b-83b2-8d2fa3780245', 'subtopic'::public.curated_course_node_type, 'Scenic and spatial design', 'Students learn how space tells the audience where they are and how to read relationships.', 0),
  ('5559ae63-c0a4-4339-85dd-e1389e70fe7c', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '9e279f3f-c0e1-46cf-9adb-a446d1f77764', 'concept'::public.curated_course_node_type, 'Ground plans and models', null, 0),
  ('2b1c04ba-1f57-4dd8-9666-0a6180d23558', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '9e279f3f-c0e1-46cf-9adb-a446d1f77764', 'concept'::public.curated_course_node_type, 'Architecture and environment', null, 1),
  ('4c4035c7-f9ad-4608-b647-174f2b9ce6c7', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '9e279f3f-c0e1-46cf-9adb-a446d1f77764', 'concept'::public.curated_course_node_type, 'Scene shifts and stage mechanics', null, 2),
