  ('0d5409c9-193c-4cc7-91dc-5067446e69d0', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'aba59175-3b15-4645-96b6-070c087327a8', 'concept'::public.curated_course_node_type, 'Silhouette and color', null, 0),
  ('8478530f-8dbe-4279-8082-330dc87b4c7d', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'aba59175-3b15-4645-96b6-070c087327a8', 'concept'::public.curated_course_node_type, 'Props as storytelling', null, 1),
  ('1ee51795-7f29-40f3-97e2-7bca459704a4', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', 'aba59175-3b15-4645-96b6-070c087327a8', 'concept'::public.curated_course_node_type, 'Research and sourcing', null, 2),
