  ('9aad74af-ef2e-43e7-8af7-172abe4e9fd0', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '6ccea679-414e-46b6-b2ba-35d0c56bb042', 'concept'::public.curated_course_node_type, 'Visibility and focus', null, 0),
  ('1218ecf6-afb1-47a2-b685-c5c2698390cc', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '6ccea679-414e-46b6-b2ba-35d0c56bb042', 'concept'::public.curated_course_node_type, 'Cueing and rhythm', null, 1),
  ('2d042b09-20dc-48c3-9985-782d5c71d35e', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '6ccea679-414e-46b6-b2ba-35d0c56bb042', 'concept'::public.curated_course_node_type, 'Music, effects, and projection', null, 2),
