  ('e5390c8a-e532-460d-933e-36ecc97c23f6', 'e7f8a9b0-1c2d-4e27-8a67-7b8c9d0e1f27', '8d8a6aa1-97a1-4d7b-acc4-be4c9e0cc8bc', 'concept'::public.curated_course_node_type, 'Load-in, run crew, and strike', null, 2),
