update public.learning_paths
set
  title = 'Introduction to Theater',
  goal = 'Introduction to Theater',
  summary = 'Introduction to Theater is a first-year survey of theatrical art, history, and practice. The course introduces students to theater as a live collaborative event, a literary and performance tradition, a technical and design practice, and a public conversation shaped by artists and audiences. Students should leave able to watch theater more intelligently, read plays as performance, recognize major roles and traditions, understand the labor behind the event, and write about performance with evidence and care.',
  data = $itthjson${"slug": "introduction-to-theater", "title": "Introduction to Theater", "description": "Introduction to Theater is a first-year survey of theatrical art, history, and practice. The course introduces students to theater as a live collaborative event, a literary and performance tradition, a technical and design practice, and a public conversation shaped by artists and audiences. Students should leave able to watch theater more intelligently, read plays as performance, recognize major roles and traditions, understand the labor behind the event, and write about performance with evidence and care.", "topics": [{"id": "a31bc414-59bd-4410-98ad-35ce96ffc910", "type": "topic", "title": "What Is Theater?", "description": "This opening section gives students a flexible definition of theater as a live, collaborative, embodied event. It helps them see theater not only as plays on stages, but as a cultural practice shaped by people, place, time, and audience.", "children": [{"id": "672888ea-9b18-4b06-8d61-f4b9bb5bc70a", "type": "subtopic", "title": "Liveness and co-presence", "children": [{"id": "5b3e94c5-581e-4873-835b-b2dd3c8bb930", "type": "concept", "title": "Live event and repeatability"}, {"id": "4823f701-1d87-48ca-bedd-1e6e2c670bfa", "type": "concept", "title": "Presence and attention"}, {"id": "5909f49f-8f78-4d10-b7d4-8c3cfc925cc5", "type": "concept", "title": "Risk, error, and immediacy"}], "description": "Students learn why theater changes when performers and audiences share time and space."}, {"id": "19425a26-3783-4944-b7a9-76c4878b85f1", "type": "subtopic", "title": "Theater as representation and action", "children": [{"id": "601ae098-9ebd-4f86-9d37-a7d6320fcc33", "type": "concept", "title": "Story and event"}, {"id": "d52debbc-cf7b-4851-a17b-e6a778003340", "type": "concept", "title": "Ritual and ceremony"}, {"id": "8cd01df6-7bcd-44de-9aba-54c54527cb32", "type": "concept", "title": "Entertainment and civic dialogue"}], "description": "The point is to understand that theater both depicts worlds and performs actions in the real world."}, {"id": "b96f48e3-c2c4-4990-ae65-2dd58e8a7abf", "type": "subtopic", "title": "Theater, performance, and everyday life", "children": [{"id": "ca2fe236-d40e-44af-8f0a-b717542ff7da", "type": "concept", "title": "Performance studies basics"}, {"id": "6f16c183-d89f-4fef-8232-989805690c52", "type": "concept", "title": "Role-playing and social behavior"}, {"id": "b6b2f1cf-733c-4a62-9491-93815fb0ddf3", "type": "concept", "title": "Public events and spectacle"}], "description": "Students distinguish formal theater from broader performance practices while seeing their overlap."}, {"id": "4f8667cc-de46-499b-9906-052aebce20df", "type": "subtopic", "title": "Theater as labor and institution", "children": [{"id": "b318f4bf-62cf-42ca-bd4a-da0b8f5ca27f", "type": "concept", "title": "Nonprofit and commercial theater"}, {"id": "5162c1a7-c556-4cce-969f-abc987b42466", "type": "concept", "title": "Education and community theater"}, {"id": "9fac6b04-0312-445b-99a3-939f4d85d891", "type": "concept", "title": "Unions, labor, and professional pathways"}], "description": "Theater is also work. Students learn the economic, organizational, and community structures behind the art."}]}, {"id": "2a284ffc-1dec-47c5-8b5f-39ac28333c27", "type": "topic", "title": "Theater's Origins and History", "description": "This section introduces theater history as a set of many traditions rather than one single lineage. Students learn how performance forms respond to religion, politics, commerce, architecture, technology, and social change.", "children": [{"id": "2f9fdf9f-7968-4c3e-a3a6-cdac6a4fa1a4", "type": "subtopic", "title": "Ritual, festival, and early performance", "children": [{"id": "cfc0133c-1f72-4d19-833d-c4bb5e1afb07", "type": "concept", "title": "Ritual action"}, {"id": "070cd4d5-62d2-47d4-b1b8-f875b8065f20", "type": "concept", "title": "Festival calendars"}, {"id": "a10ac4b8-0d44-4de8-b217-947e341ad036", "type": "concept", "title": "Myth and community identity"}], "description": "Students explore how performance emerges from communal gatherings, ceremony, storytelling, and embodied memory."}, {"id": "83aa2381-6e4a-4221-ae03-1f94a6720435", "type": "subtopic", "title": "Classical and premodern traditions", "children": [{"id": "fea0ba85-85ff-48b1-9ccf-1201ecb4aa45", "type": "concept", "title": "Greek tragedy and comedy"}, {"id": "b117f496-d855-4c0c-945f-785cd3934619", "type": "concept", "title": "Sanskrit drama and Natyashastra"}, {"id": "7164a2a3-fb3f-474d-8063-3e77f9b26c0b", "type": "concept", "title": "Noh, Kabuki, and Chinese opera"}], "description": "The goal is to recognize major forms while avoiding the idea that one tradition explains all theater."}, {"id": "26a338ec-2cc3-486d-9470-f884a51f5e32", "type": "subtopic", "title": "Commercial, court, and public theaters", "children": [{"id": "6946d37b-20d2-4fb5-a723-e6e1b576d2d1", "type": "concept", "title": "Elizabethan playhouses"}, {"id": "e5f6a9f5-dc42-45fa-bf4b-6f9bdb60d09e", "type": "concept", "title": "Commedia dell'arte"}, {"id": "0bb5f415-ef13-4f18-bba0-e2b41384b04a", "type": "concept", "title": "Restoration and neoclassical stages"}], "description": "Students learn how architecture, patronage, censorship, and audiences shape theater forms."}, {"id": "f0ca412e-46ab-4b5d-b615-8f4201a708f4", "type": "subtopic", "title": "Modern and contemporary theater", "children": [{"id": "0f039489-b202-4718-9971-08f6a9865b81", "type": "concept", "title": "Realism and naturalism"}, {"id": "81639dde-126e-44aa-88bb-9e603899c33d", "type": "concept", "title": "Modernist and avant-garde movements"}, {"id": "53682c45-7666-4ec0-8480-e929532fc572", "type": "concept", "title": "Postcolonial, feminist, queer, and community-based theater"}], "description": "Students trace shifts from realism to modernism, experimental performance, devised work, and global contemporary practice."}]}, {"id": "8966846b-9708-4c88-b4c7-9f10b5516a64", "type": "topic", "title": "The Collaborative Art Form", "description": "Theater is made through interdependent craft. This section helps students understand how creative, technical, managerial, and audience roles connect.", "children": [{"id": "36e68c00-8182-456d-b101-0be9b10963b4", "type": "subtopic", "title": "Production roles and responsibilities", "children": [{"id": "cf08399b-d49b-44de-b605-07c057cc0dd0", "type": "concept", "title": "Creative team"}, {"id": "89628b99-bc3c-495e-80be-5bc69d10756a", "type": "concept", "title": "Production team"}, {"id": "f8f97755-86a4-4963-ad8f-c13fd88fb70f", "type": "concept", "title": "Front-of-house and producing"}], "description": "Students learn who does what in a production and how those responsibilities overlap."}, {"id": "748d474a-a3b9-4304-829f-8379a71acf01", "type": "subtopic", "title": "Communication across departments", "children": [{"id": "81fbcccc-1bb4-4e70-ac3a-4fcda4176a3e", "type": "concept", "title": "Production meetings"}, {"id": "c9caff4f-d9d9-4d92-8110-18a44a9640a7", "type": "concept", "title": "Rehearsal reports"}, {"id": "08b3ac92-880a-4c55-9201-9bb8bf683dec", "type": "concept", "title": "Shared vocabulary"}], "description": "The point is to see collaboration as a skill, not just a nice value."}, {"id": "a46593f2-13ac-4a1d-9c17-6a208f627271", "type": "subtopic", "title": "From idea to performance", "children": [{"id": "2b3aeea9-e78b-4c7c-a2cc-998381cf3624", "type": "concept", "title": "Season planning"}, {"id": "7c6ea787-7eda-4a67-8210-d88d21de124c", "type": "concept", "title": "Rehearsal and design process"}, {"id": "ea43096f-a8a9-4a0c-821d-fc85892896b9", "type": "concept", "title": "Tech, previews, opening, and strike"}], "description": "Students map the production process from script selection to closing night."}, {"id": "8898b7f9-b2d3-46c5-b602-66a609fbf0f8", "type": "subtopic", "title": "Conflict, care, and ensemble culture", "children": [{"id": "f6f8bb66-ac43-4e59-ac99-7645e27de235", "type": "concept", "title": "Room agreements"}, {"id": "e0866be2-ff0b-428c-bea6-a54fd60ced2c", "type": "concept", "title": "Feedback norms"}, {"id": "98325d6c-fea1-4495-a7b3-022ed0e8e89e", "type": "concept", "title": "Accessibility and inclusion"}], "description": "Collaboration requires trust, boundaries, and accountability."}]}, {"id": "7e303ebd-4530-4961-a5fe-ea290021889c", "type": "topic", "title": "The Playwright's Role", "description": "This section introduces the playwright as an architect of action, language, image, and possibility. Students learn how scripts invite performance choices rather than simply recording dialogue.", "children": [{"id": "c2a42d42-5f67-4b63-8b32-8aeb4bb046af", "type": "subtopic", "title": "Dramatic action and structure", "children": [{"id": "b0f012f8-5641-4359-8107-79210dfbe0f8", "type": "concept", "title": "Conflict and stakes"}, {"id": "990c0512-7d45-4421-901d-10c5b972a97b", "type": "concept", "title": "Events and turning points"}, {"id": "af1008aa-d99e-4e7a-87fe-cd5617f41f24", "type": "concept", "title": "Beginnings, middles, and endings"}], "description": "Students learn to notice what changes in a play and how scenes create pressure."}, {"id": "b850e703-0c40-42ab-a12b-29d6696f787a", "type": "subtopic", "title": "Character, dialogue, and voice", "children": [{"id": "7306c5cd-c6d8-4f53-889d-16cd5018f705", "type": "concept", "title": "Character desire"}, {"id": "9fd2e85d-e628-4509-9ef8-d1f8d96d0654", "type": "concept", "title": "Subtext"}, {"id": "686987f0-9d6d-4db5-a063-808b8c266823", "type": "concept", "title": "Voice and rhythm"}], "description": "The goal is to understand how playwrights make people speak, want, hide, reveal, and transform."}, {"id": "7718933f-d43a-486a-ad6a-391402899d78", "type": "subtopic", "title": "Theatricality and form", "children": [{"id": "a866eba6-eb80-42ac-b4a1-48bd7d28fd90", "type": "concept", "title": "Monologue and chorus"}, {"id": "6b71dd3e-2e1b-484b-aeb9-8a3468c00ca5", "type": "concept", "title": "Time shifts and direct address"}, {"id": "34ddb5ab-9484-4832-9028-be704e16e38a", "type": "concept", "title": "Image, metaphor, and spectacle"}], "description": "Students examine how playwrights use nonrealistic, poetic, fragmented, musical, or physical forms."}, {"id": "9b31184e-2465-4b3c-b164-a250225df083", "type": "subtopic", "title": "New-play development", "children": [{"id": "62bd541d-d05e-4e80-b537-ef48bc9ac6f1", "type": "concept", "title": "Table reads"}, {"id": "86cfa10f-7154-4f76-845e-6031b08fedca", "type": "concept", "title": "Dramaturgical feedback"}, {"id": "e583f2c4-a2de-4a2c-9d55-ca42aa1acebe", "type": "concept", "title": "Playwright-director collaboration"}], "description": "Students learn that plays are often revised through readings, workshops, dramaturgy, and production."}]}, {"id": "ef30b565-5ff1-4c59-9582-e11cbcb55826", "type": "topic", "title": "The Director's Role", "description": "The director turns analysis into a shared production process. Students learn how directors shape vision, rehearsal, staging, actor collaboration, and design coherence.", "children": [{"id": "bc282f50-96e2-41bf-89f8-cf00de9c4a67", "type": "subtopic", "title": "Interpretation and vision", "children": [{"id": "40b384a8-500b-45de-8bda-877543fbacba", "type": "concept", "title": "Director's concept"}, {"id": "d43f5a02-6683-4fed-8ee2-da6edc5d2ddb", "type": "concept", "title": "Audience and context"}, {"id": "2e81d2c6-a982-45fd-8b07-edb9f49c8704", "type": "concept", "title": "Core question or image"}], "description": "Students learn how directors make a case for why this play should be performed in a particular way."}, {"id": "f3525b66-cb19-49d3-b480-c26b8bbb32ff", "type": "subtopic", "title": "Rehearsal leadership", "children": [{"id": "46bf3985-74cd-4cb8-b3fb-7b961e37f278", "type": "concept", "title": "Table work"}, {"id": "9756eb31-6d6f-4304-b9a1-f8dbe1c3763d", "type": "concept", "title": "Blocking"}, {"id": "cd91cdf6-386a-4982-bd2e-4a8318cfcfcc", "type": "concept", "title": "Runs, notes, and revision"}], "description": "The point is to understand rehearsal as planned discovery."}, {"id": "f2bacb5b-df63-42da-b3ff-7bcb52c20c77", "type": "subtopic", "title": "Staging and composition", "children": [{"id": "4c49cf0d-617a-42c6-8738-d5a2b545e363", "type": "concept", "title": "Stage pictures"}, {"id": "40813b7d-8e64-4401-a028-324571e2efa5", "type": "concept", "title": "Movement and stillness"}, {"id": "e436b33a-ee0d-4da8-b821-eb4a641202c7", "type": "concept", "title": "Transitions and pacing"}], "description": "Students see how directors use space, bodies, focus, and rhythm to tell the story."}, {"id": "acb90297-7481-48fe-98b8-ead7c165010b", "type": "subtopic", "title": "Collaboration with designers and stage managers", "children": [{"id": "341e4914-f459-47ac-85e4-fc7eb36c63f4", "type": "concept", "title": "Design meetings"}, {"id": "aff221e0-9b4d-4e4a-9788-4dd3d9fa4c50", "type": "concept", "title": "Prompt books and rehearsal reports"}, {"id": "e298df6c-b4b0-4c4c-841b-0fda43a8bb81", "type": "concept", "title": "Tech rehearsal priorities"}], "description": "Directors coordinate with many artists while respecting each craft area."}]}, {"id": "ba398fa2-54ba-428d-b3a8-2dedda2ccf10", "type": "topic", "title": "The Actor's Role", "description": "Actors make theater visible and audible through body, voice, imagination, listening, and repeatable action. This section introduces actor craft without reducing it to personality or memorization.", "children": [{"id": "fa5ea237-4d40-4592-84d3-15ed4663ca11", "type": "subtopic", "title": "The actor's instrument", "children": [{"id": "11a759f0-b0a9-4a59-b198-52265f4135d7", "type": "concept", "title": "Body and alignment"}, {"id": "51f6dea7-c0b7-43c1-b2b5-9d69d2e3a41c", "type": "concept", "title": "Voice and breath"}, {"id": "ec78a964-28a5-4d43-aa90-a609b68f4cd8", "type": "concept", "title": "Focus and concentration"}], "description": "Students learn that acting uses trained physical, vocal, emotional, and imaginative skills."}, {"id": "627cf655-f18b-4fdb-b22a-64d4f58cea0f", "type": "subtopic", "title": "Objectives and actions", "children": [{"id": "737fe25a-e3c2-40e7-9db1-1d888ba23444", "type": "concept", "title": "Given circumstances"}, {"id": "96178490-fbd0-4669-a1d9-515a662921d9", "type": "concept", "title": "Objectives and obstacles"}, {"id": "5e253c74-9906-482d-8c85-9190a22b5a8e", "type": "concept", "title": "Tactics and playable verbs"}], "description": "The point is to understand acting as doing, not pretending in a vague way."}, {"id": "a5145b72-1623-4c63-a2f5-3a0348a41637", "type": "subtopic", "title": "Ensemble and listening", "children": [{"id": "878f5550-cb6c-4fa9-b5af-540b1d48a46a", "type": "concept", "title": "Cue pickup"}, {"id": "11f1180c-e9a7-4f83-9d4d-40581bec96c2", "type": "concept", "title": "Status and relationship"}, {"id": "635039f7-58a7-4733-9e66-91aff8d61dad", "type": "concept", "title": "Improvisation and trust"}], "description": "Theater depends on responsiveness among performers."}, {"id": "977bd816-b8bb-4bd6-8737-9467bf58fb98", "type": "subtopic", "title": "Character and performance style", "children": [{"id": "af5456ae-2778-4009-9ef1-7d43581f8087", "type": "concept", "title": "Character research"}, {"id": "b06594e8-2907-4723-9a1f-f5c2caaae533", "type": "concept", "title": "Style and genre"}, {"id": "bd561bc7-7a63-4030-b48c-56fc64503f73", "type": "concept", "title": "Repeatability and spontaneity"}], "description": "Students compare approaches to realism, heightened language, physical theater, musical performance, and comedy."}]}, {"id": "ccadba56-99ef-486b-83b2-8d2fa3780245", "type": "topic", "title": "Designers and Technicians", "description": "This section gives students production literacy. They learn how scenery, costume, light, sound, props, projections, stage management, and technical work shape meaning.", "children": [{"id": "9e279f3f-c0e1-46cf-9adb-a446d1f77764", "type": "subtopic", "title": "Scenic and spatial design", "children": [{"id": "5559ae63-c0a4-4339-85dd-e1389e70fe7c", "type": "concept", "title": "Ground plans and models"}, {"id": "2b1c04ba-1f57-4dd8-9666-0a6180d23558", "type": "concept", "title": "Architecture and environment"}, {"id": "4c4035c7-f9ad-4608-b647-174f2b9ce6c7", "type": "concept", "title": "Scene shifts and stage mechanics"}], "description": "Students learn how space tells the audience where they are and how to read relationships."}, {"id": "aba59175-3b15-4645-96b6-070c087327a8", "type": "subtopic", "title": "Costume, props, and visual detail", "children": [{"id": "0d5409c9-193c-4cc7-91dc-5067446e69d0", "type": "concept", "title": "Silhouette and color"}, {"id": "8478530f-8dbe-4279-8082-330dc87b4c7d", "type": "concept", "title": "Props as storytelling"}, {"id": "1ee51795-7f29-40f3-97e2-7bca459704a4", "type": "concept", "title": "Research and sourcing"}], "description": "The goal is to see clothing and objects as character, culture, period, status, and action."}, {"id": "6ccea679-414e-46b6-b2ba-35d0c56bb042", "type": "subtopic", "title": "Lighting, sound, and media", "children": [{"id": "9aad74af-ef2e-43e7-8af7-172abe4e9fd0", "type": "concept", "title": "Visibility and focus"}, {"id": "1218ecf6-afb1-47a2-b685-c5c2698390cc", "type": "concept", "title": "Cueing and rhythm"}, {"id": "2d042b09-20dc-48c3-9985-782d5c71d35e", "type": "concept", "title": "Music, effects, and projection"}], "description": "Students learn how time, attention, mood, and atmosphere are designed."}, {"id": "8d8a6aa1-97a1-4d7b-acc4-be4c9e0cc8bc", "type": "subtopic", "title": "Technical theater and safety", "children": [{"id": "39ea12a9-4cb9-4bbf-b92e-d925a8d02b43", "type": "concept", "title": "Stage management"}, {"id": "303180b4-97cc-4a37-8428-480b6c1468a4", "type": "concept", "title": "Technical direction"}, {"id": "e5390c8a-e532-460d-933e-36ecc97c23f6", "type": "concept", "title": "Load-in, run crew, and strike"}], "description": "Students understand the skilled labor and safety systems that make performance possible."}]}, {"id": "c96b25bd-c3f1-4186-9c29-ca1acea62022", "type": "topic", "title": "Reading and Analyzing Plays", "description": "This section teaches students to read plays as blueprints for performance. The goal is to move from plot summary to evidence-based interpretation.", "children": [{"id": "1365b820-196e-4164-a2bc-0474f18c97bd", "type": "subtopic", "title": "Reading for action", "children": [{"id": "cbe72fc7-e7f2-4942-9a48-b290176d182f", "type": "concept", "title": "Events and beats"}, {"id": "25f15e0c-c68c-4173-aca7-6696e543e135", "type": "concept", "title": "Objectives and obstacles"}, {"id": "ececa8d5-e688-40df-a468-85dd949685a3", "type": "concept", "title": "Conflict and tactics"}], "description": "Students learn to identify what characters do to each other and what changes moment by moment."}, {"id": "0974de76-df0e-49d3-b2cb-0ef373c9060a", "type": "subtopic", "title": "World of the play", "children": [{"id": "4bc97fb0-1c07-4647-a71e-6802b37411ce", "type": "concept", "title": "Place and time"}, {"id": "9f38a267-4208-436f-a294-b92aa6ec7d58", "type": "concept", "title": "Class, culture, and power"}, {"id": "9c3aaf9a-0733-4ee9-a001-35aea8c4fbe8", "type": "concept", "title": "Atmosphere and environment"}], "description": "Students identify the social, historical, material, and emotional rules of the script."}, {"id": "6233bf95-6fb6-4ec1-82c1-15de73018d1f", "type": "subtopic", "title": "Genre, style, and structure", "children": [{"id": "4fa2cabf-eacc-4c15-a285-2af2499a88a1", "type": "concept", "title": "Comedy, tragedy, and melodrama"}, {"id": "7c7f2f4e-0a58-40b5-9832-9f714d8c6d8d", "type": "concept", "title": "Realism and nonrealism"}, {"id": "11a432e7-7601-447e-a91e-5240a8b4693f", "type": "concept", "title": "Episodic, circular, and fragmented structures"}], "description": "The point is to understand how a play asks to be performed."}, {"id": "ad1ff94d-5275-4bbe-8517-ef4527e53047", "type": "subtopic", "title": "Writing about plays", "children": [{"id": "da5cebea-6887-4cf0-9580-599f89605255", "type": "concept", "title": "Thesis and evidence"}, {"id": "018a9be8-c58b-4069-ae9a-a0750be75866", "type": "concept", "title": "Quoting dialogue"}, {"id": "4c8fcc84-86b7-4da5-b5c6-309a4c73453e", "type": "concept", "title": "Connecting script and staging"}], "description": "Students practice claims supported by specific textual and production evidence."}]}, {"id": "70da17ab-e3f9-4383-ade1-1f00d5ba3e1e", "type": "topic", "title": "The Audience Experience", "description": "Theater is completed by spectators. This section studies how audiences perceive, interpret, respond, and participate in live performance.", "children": [{"id": "0dd2cb92-89b9-42b7-8979-0929cb4335d3", "type": "subtopic", "title": "Spectatorship and attention", "children": [{"id": "80c58051-4217-4173-8fbf-9ddadf77baa7", "type": "concept", "title": "Focus and framing"}, {"id": "64dc96aa-c903-498d-bb3d-5a5078684502", "type": "concept", "title": "Shared laughter and silence"}, {"id": "cc1fc190-7fe9-4286-94f6-edf82c825d51", "type": "concept", "title": "Attention over time"}], "description": "Students learn that watching theater is an active, embodied practice."}, {"id": "a1bbeb1a-6416-44f5-b637-3d0dff04c137", "type": "subtopic", "title": "Space and community", "children": [{"id": "62f271a5-bbb2-4b85-9317-3d3230c047bd", "type": "concept", "title": "Proscenium, thrust, arena, and black box"}, {"id": "67a4f30b-d8c7-4dfa-9b3c-129afce5d5b8", "type": "concept", "title": "Site-specific and immersive work"}, {"id": "6072e141-2a57-4d23-8442-da0fe1950734", "type": "concept", "title": "Audience demographics and community context"}], "description": "The arrangement of audience and performers shapes meaning."}, {"id": "1cbfdf86-6a00-4515-86f5-c3017a61eea0", "type": "subtopic", "title": "Theatergoing skills", "children": [{"id": "ec7a9318-a7ee-409a-9aef-83ffcf9c80c0", "type": "concept", "title": "Preparation and context"}, {"id": "9f32f907-ca8f-40b1-bb91-745567a811de", "type": "concept", "title": "Etiquette and access"}, {"id": "21a5550a-38df-4c88-901c-1de44b339c67", "type": "concept", "title": "Post-show discussion"}], "description": "Students learn practical and ethical habits for attending live performance."}, {"id": "2aa47aba-f4af-4326-80d8-ae43b6f730e0", "type": "subtopic", "title": "Accessibility and inclusion", "children": [{"id": "fcfd2bb6-e7fa-4a22-80de-602a18ae792d", "type": "concept", "title": "Captioning and audio description"}, {"id": "cc1e7404-1e1c-4456-aea4-9545ff8339c8", "type": "concept", "title": "Relaxed performances"}, {"id": "99057b17-4a79-4a3e-bfcf-0bf73b92b551", "type": "concept", "title": "Cultural access and affordability"}], "description": "A world-class theater course asks who can attend, perceive, and feel welcome."}]}, {"id": "7d9c8f8d-4334-4625-81c9-0367381fb655", "type": "topic", "title": "Theater Criticism and Response", "description": "This final section teaches students to respond to performance with precision, generosity, and evidence. Criticism becomes a way to deepen public conversation about theater.", "children": [{"id": "26af4bd3-07eb-4370-b06e-52233399e3e8", "type": "subtopic", "title": "Description before evaluation", "children": [{"id": "ed7225c8-f05f-4bce-9c0b-687e87e84d31", "type": "concept", "title": "What was seen and heard"}, {"id": "9ad2ebc7-6bee-48a2-a8b2-58147b58c71f", "type": "concept", "title": "Design and performance evidence"}, {"id": "2c36ef98-a6d3-4dd1-8c34-8547a9935136", "type": "concept", "title": "Separating taste from analysis"}], "description": "Students learn to observe accurately before deciding whether something worked."}, {"id": "bce055ba-1361-4d94-937f-4ef925f3e71c", "type": "subtopic", "title": "Craft vocabulary", "children": [{"id": "663512d9-a4cf-4805-b481-c3bd2c530988", "type": "concept", "title": "Acting, directing, and design terms"}, {"id": "79cfabb3-7842-44a8-84d3-506efeedab95", "type": "concept", "title": "Pacing and rhythm"}, {"id": "f3e38f73-59b3-4957-b777-518cdfdba8f7", "type": "concept", "title": "Composition and focus"}], "description": "The goal is to use theater-specific language rather than vague praise or dislike."}, {"id": "52415f53-6bc4-4b81-828e-3c0370c3d89e", "type": "subtopic", "title": "Context and ethics", "children": [{"id": "406064b1-e1b0-4b85-b24a-08f3fb07e2ff", "type": "concept", "title": "Representation and power"}, {"id": "facd277b-a8fe-4fe4-be67-79f610111272", "type": "concept", "title": "Historical and social context"}, {"id": "557546aa-b492-4b3d-8d70-3eeafeb62656", "type": "concept", "title": "Reviewer position and bias"}], "description": "Students learn that criticism has responsibilities to artists, audiences, cultures, and communities."}, {"id": "e801d2f2-d4ac-4692-8042-922dbc5f10ca", "type": "subtopic", "title": "Forms of response", "children": [{"id": "d0031abf-b24d-4e3d-8ba3-170e756c0aba", "type": "concept", "title": "Performance review"}, {"id": "f101481e-4be2-4cc1-8d44-18eda3a27f41", "type": "concept", "title": "Reflection paper"}, {"id": "a30f8e5b-6b95-41cb-972c-a8d3beef3242", "type": "concept", "title": "Comparative response and discussion"}], "description": "Students practice multiple modes of critical writing and speaking."}]}], "dbBacked": true}$itthjson$::jsonb,
